.tab-strip {
  display: flex;
  flex-direction: column;
  color: var(--ink);
  font: inherit;
}

.tab-strip__list {
  display: flex;
  gap: 0.25rem;
  border-bottom: 1px solid var(--hair);
}

.tab-strip__tab {
  position: relative;
  font: inherit;
  font-size: clamp(0.875rem, 0.8rem + 0.4vw, 1.0625rem);
  color: var(--muted);
  background: transparent;
  border: 0;
  border-radius: 999px;
  padding: 0.5rem 0.9rem;
  margin-bottom: -1px;
  cursor: pointer;
  transition: color 150ms ease, background-color 150ms ease;
}

.tab-strip__tab:hover {
  color: var(--ink);
  background: var(--myelin-wash);
}

/* The selected tab is marked three ways, so it does not depend on colour alone:
   heavier type, a solid underline bar, and the ink colour. */
.tab-strip__tab[aria-selected="true"] {
  color: var(--ink);
  font-weight: 600;
}

.tab-strip__tab[aria-selected="true"]::after {
  content: "";
  position: absolute;
  left: 0.9rem;
  right: 0.9rem;
  bottom: 0;
  height: 3px;
  border-radius: 999px;
  background: var(--myelin);
}

.tab-strip__panel {
  padding: clamp(0.75rem, 0.6rem + 0.6vw, 1.25rem) 0;
  color: var(--ink);
}

:root[data-motion="reduce"] .tab-strip__tab {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .tab-strip__tab {
    transition: none;
  }
}
